const input = $json || {};
const original = $('Preparar').first().json || {};
const link = $('Buscar vinculo').first()?.json || {};
const rawText = String(original.texto_mensaje || '').trim();
const normalizedText = rawText.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const statusCode = Number(input.statusCode || input.responseCode || input.code || input.status || 0);
const backendReply = [input.reply_text, input.message_to_patient_es, input.message].find((value) => typeof value === 'string' && value.trim()) || '';
const linkedPatientId = link.paciente_id || link.patient_id || null;
const linkedProfessionalId = link.profesional_id || link.professional_id || null;

function parseRequestedSlot(text) {
  const normalized = String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = new Date();
  let target = null;

  if (/\bmanana\b/.test(normalized)) {
    target = new Date(now);
    target.setDate(target.getDate() + 1);
  } else if (/\bhoy\b/.test(normalized)) {
    target = new Date(now);
  } else {
    const dowMap = { domingo: 0, lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6 };
    for (const [name, targetDow] of Object.entries(dowMap)) {
      if (normalized.includes(name)) {
        target = new Date(now);
        let daysAhead = targetDow - target.getDay();
        if (daysAhead <= 0) daysAhead += 7;
        target.setDate(target.getDate() + daysAhead);
        break;
      }
    }
  }

  const timeMatchFull = normalized.match(/a\s+las?\s+(\d{1,2})(?::(\d{2}))?/);
  const timeMatchStd = !timeMatchFull && normalized.match(/(?<!\d)(\d{1,2}):(\d{2})(?!\d)/);
  const timeMatchH = !timeMatchFull && !timeMatchStd && normalized.match(/(?<!\d)(\d{1,2})\s*h(?:horas?)?(?!\d)/);
  const tm = timeMatchFull || timeMatchStd || timeMatchH;
  if (!target || !tm) return null;

  const hour = Number(tm[1]);
  const minute = Number(tm[2] || 0);
  if (Number.isNaN(hour) || Number.isNaN(minute)) return null;

  const totalMin = hour * 60 + minute;
  const withinHours = (totalMin >= 9 * 60 && totalMin < 13 * 60) || (totalMin >= 15 * 60 && totalMin < 19 * 60);

  const pad = (n) => String(n).padStart(2, '0');
  const year = target.getFullYear();
  const month = target.getMonth() + 1;
  const day = target.getDate();
  const refDate = new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
  const tzParts = new Intl.DateTimeFormat('en', { timeZone: 'Europe/Madrid', timeZoneName: 'shortOffset' }).formatToParts(refDate);
  const tzName = tzParts.find((p) => p.type === 'timeZoneName')?.value || 'GMT+1';
  const offsetMatch = tzName.match(/GMT([+-])(\d+)(?::(\d+))?/);
  const offsetSign = offsetMatch?.[1] || '+';
  const offsetH = pad(parseInt(offsetMatch?.[2] || '1', 10));
  const offsetM = pad(parseInt(offsetMatch?.[3] || '0', 10));
  const tzOffset = `${offsetSign}${offsetH}:${offsetM}`;
  const slotStart = `${year}-${pad(month)}-${pad(day)}T${pad(hour)}:${pad(minute)}:00${tzOffset}`;
  let endHour = hour;
  let endMinute = minute + 60;
  if (endMinute >= 60) { endHour += 1; endMinute -= 60; }
  const slotEnd = `${year}-${pad(month)}-${pad(day)}T${pad(endHour)}:${pad(endMinute)}:00${tzOffset}`;

  const dayLabel = /\bmanana\b/.test(normalized)
    ? 'manana'
    : /\bhoy\b/.test(normalized)
      ? 'hoy'
      : `${pad(day)}/${pad(month)}/${year}`;

  return {
    slotStart,
    slotEnd,
    hour,
    minute,
    withinHours,
    humanLabel: `${dayLabel} a las ${pad(hour)}:${pad(minute)}`,
  };
}

function hasClinicalReason(text = '') {
  const normalized = String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  return /\b(dolor|molestia|lesion|contractura|cervical|lumbar|espalda|hombro|rodilla|tobillo|cadera|cuello|seguimiento|revision|rehabilitacion|ciatica)\b/.test(normalized);
}

function isGreeting(text = '') {
  const normalized = String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  return /^(hola|holaa+|buenas|buenos dias|buenas tardes|buenas noches|hey|ey)\b/.test(normalized);
}

function looksLikeAppointmentRequest(text = '', requestedSlot = null) {
  const normalized = String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  return Boolean(requestedSlot) || /\b(cita|agendar|agenda|reservar|reserva|hueco|hora|disponibilidad|confirmar|confirmo|vale|ok)\b/.test(normalized);
}

const slotFromRawText = parseRequestedSlot(rawText);
const slotFromBackendReply = parseRequestedSlot(backendReply);
const effectiveSlot = slotFromRawText || slotFromBackendReply;
const rawClinicalReason = hasClinicalReason(rawText);
const replyClinicalReason = hasClinicalReason(backendReply);
const effectiveReasonText = rawClinicalReason ? rawText : (replyClinicalReason ? backendReply : rawText);
const appointmentIntent = looksLikeAppointmentRequest(rawText, effectiveSlot);
const backendFailed = Boolean(input.error) || Boolean(statusCode && statusCode >= 400);
const contradictoryOutsideHours = Boolean(effectiveSlot?.withinHours) && /(horario disponible comienza a las 9:00|elige un horario dentro de esos rangos|dentro de esos rangos|sin embargo, el horario disponible comienza)/i.test(backendReply);
const backendSuggestsPendingConfirmation = /(solo necesito confirmar|te parece bien|voy a registrar tu cita|un momento, por favor)/i.test(backendReply);
const readyToBook = Boolean(effectiveSlot?.withinHours) && (rawClinicalReason || replyClinicalReason) && linkedPatientId && linkedProfessionalId && (contradictoryOutsideHours || backendFailed || backendSuggestsPendingConfirmation);

let reply = String(backendReply || '').trim();
let forceW1 = false;

if (readyToBook) {
  forceW1 = true;
  reply = `Perfecto, ${effectiveSlot.humanLabel}. Estoy tramitando tu cita ahora mismo.`;
} else if (contradictoryOutsideHours && effectiveSlot?.withinHours) {
  reply = `Perfecto, ${effectiveSlot.humanLabel} encaja dentro del horario. Para gestionarlo bien, dime brevemente el motivo de la consulta.`;
} else if (isGreeting(rawText)) {
  reply = 'Hola. Soy Carla, la asistente de citas de la clinica. Dime que dia y hora te vendria bien y el motivo de la consulta.';
} else if (slotFromRawText?.withinHours && !rawClinicalReason) {
  reply = `Perfecto, ${slotFromRawText.humanLabel} me encaja. Para dejar la cita bien registrada, dime brevemente el motivo de la consulta.`;
} else if (slotFromRawText && !slotFromRawText.withinHours) {
  reply = 'Puedo ayudarte con la cita, pero esa hora queda fuera del horario habitual. Dime una franja entre 9:00 y 13:00 o entre 15:00 y 19:00.';
} else if (!reply && appointmentIntent && !effectiveSlot) {
  reply = 'Claro. Dime por favor que dia te viene bien, a que hora y el motivo de la consulta.';
} else if (!reply && backendFailed) {
  reply = 'He recibido tu mensaje. Ahora mismo hay una incidencia tecnica y te respondere en breve.';
} else if (!reply) {
  reply = 'He recibido tu mensaje. Enseguida te doy respuesta.';
}

return [{
  json: {
    reply_text: reply.slice(0, 3500),
    response_status: statusCode || null,
    backend_ok: !backendFailed,
    force_w1: forceW1,
    force_w1_payload: forceW1
      ? {
          request_id: `${original.request_id || 'req'}_w1_guardrail`,
          source: 'telegram_guardrail',
          channel: 'telegram',
          patient_id: linkedPatientId,
          professional_id: linkedProfessionalId,
          chat_id: String(original.chat_id || ''),
          username: original.username || null,
          message_text: effectiveReasonText,
          slot_start: effectiveSlot.slotStart,
          slot_end: effectiveSlot.slotEnd,
          timezone: 'Europe/Madrid',
        }
      : null,
    guardrail_slot_label: effectiveSlot?.humanLabel || null,
  }
}];

const original = $('Preparar respuesta').first().json || {};
const input = $json || {};
let reply = '';
if (typeof input.message_to_patient_es === 'string' && input.message_to_patient_es.trim()) {
  reply = input.message_to_patient_es.trim();
} else if (typeof input.reply_text === 'string' && input.reply_text.trim()) {
  reply = input.reply_text.trim();
} else if (typeof original.reply_text === 'string' && original.reply_text.trim()) {
  reply = original.reply_text.trim();
}
if (!reply) {
  reply = 'Estoy revisando tu solicitud de cita y te confirmo en breve.';
}
return [{ json: { reply_text: reply.slice(0, 3500) } }];
